const exportData = $input.first().json;
const files = exportData.files || [];
const results = [];

// 1. Arquivo Consolidado do Banco de Dados com Data do Dia
const now = new Date();
const pad = (n) => String(n).padStart(2, '0');
const dateStr = `${now.getFullYear()}-${pad(now.getMonth() + 1)}-${pad(now.getDate())}`;
const dbFileName = `agrovenda_backup_vendas_${dateStr}.json`;
const dbContent = JSON.stringify(exportData || {}, null, 2);

results.push({
  json: {
    fileName: dbFileName,
    tipo: 'Banco de Dados'
  },
  binary: {
    data: await this.helpers.prepareBinaryData(
      Buffer.from(dbContent, 'utf8'),
      dbFileName,
      'application/json'
    )
  }
});

// 2. Arquivos de Notas Fiscais e Comprovantes (apenas com conteúdo válido)
for (const f of files) {
  if (f.contentBase64 && f.sizeBytes > 100) {
    const mimeType = f.filename.toLowerCase().endsWith('.pdf') ? 'application/pdf' :
                     (f.filename.toLowerCase().endsWith('.xml') ? 'application/xml' :
                     (f.filename.toLowerCase().endsWith('.png') ? 'image/png' :
                     (f.filename.toLowerCase().endsWith('.jpg') || f.filename.toLowerCase().endsWith('.jpeg') ? 'image/jpeg' : 'application/octet-stream')));

    const fileBuffer = Buffer.from(f.contentBase64, 'base64');

    results.push({
      json: {
        fileName: f.filename,
        sizeBytes: f.sizeBytes,
        tipo: 'Nota Fiscal / Documento'
      },
      binary: {
        data: await this.helpers.prepareBinaryData(
          fileBuffer,
          f.filename,
          mimeType
        )
      }
    });
  }
}

return results;
